INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Isolation Level immer auf maximale Isolation eingestellt?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Anforderungen"}, {"text": "Ja", "correct": false, "because": "Nicht standardmäßig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wahl eines Isolation Levels?', 3, '[{"text": "Datenkonsistenz", "correct": true, "because": "Schützt vor Anomalien"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Konsistenz wichtiger"}, {"text": "Minimale Ressourcen", "correct": false, "because": "Funktion zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Isolation Levels gibt es?', 5, '[{"text": "Read Uncommitted", "correct": true, "because": "Geringste Isolation"}, {"text": "Serializable", "correct": true, "because": "Höchste Isolation"}, {"text": "High Speed", "correct": false, "because": "Kein Isolation Level"}, {"text": "Flexible", "correct": false, "because": "Kein technischer Begriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Read Committed verhindert Dirty Reads. b) Serializable ist immer performant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Serializable kann langsam sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Isolation Levels?', 4, '[{"text": "Konsistenzanforderungen", "correct": false, "because": "Kern der Entscheidung"}, {"text": "Transaktionskonflikte", "correct": false, "because": "Wichtig für Isolation"}, {"text": "Farbcodierung", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Read Uncommitted Dirty Reads erlaubt?', 2, '[{"text": "Ja", "correct": true, "because": "Liest unbestätigte Daten"}, {"text": "Nein", "correct": false, "because": "Hauptmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Isolation Level wähle ich für maximale Konsistenz?', 3, '[{"text": "Serializable", "correct": true, "because": "Verhindert alle Anomalien"}, {"text": "Read Uncommitted", "correct": false, "because": "Geringste Isolation"}, {"text": "Repeatable Read", "correct": false, "because": "Nicht vollständig isoliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme lösen Isolation Levels?', 5, '[{"text": "Dirty Reads", "correct": true, "because": "Unbestätigte Daten"}, {"text": "Phantom Reads", "correct": true, "because": "Neue Zeilen während Transaktion"}, {"text": "Schnellere Abfragen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Repeatable Read verhindert Phantom Reads. b) Read Committed ist am sichersten. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Repeatable Read lässt Phantom Reads zu, Serializable ist sicherer"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Isolation Levels?', 4, '[{"text": "Transaktionssteuerung", "correct": false, "because": "Grundlage"}, {"text": "Konsistenzprüfung", "correct": false, "because": "Definiert Level"}, {"text": "Spielemodus", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Read Committed für alle Szenarien ausreichend?', 2, '[{"text": "Nein", "correct": true, "because": "Erlaubt Non-Repeatable Reads"}, {"text": "Ja", "correct": false, "because": "Begrenzt in Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Wahl eines Isolation Levels?', 4, '[{"text": "Konsistenzbedarf", "correct": true, "because": "Definiert Schutz"}, {"text": "Transaktionsvolumen", "correct": true, "because": "Beeinflusst Performance"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Serializable keine Nachteile hat. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann Performance mindern"}, {"text": "Ja", "correct": false, "because": "Nachteile vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei hohem Transaktionsaufkommen?', 3, '[{"text": "Read Committed", "correct": true, "because": "Gute Balance zwischen Konsistenz und Geschwindigkeit"}, {"text": "Serializable", "correct": false, "because": "Zu restriktiv"}, {"text": "Read Uncommitted", "correct": false, "because": "Zu unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Isolation Levels verhindern Konflikte. b) Sie steigern immer die Performance.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Performance kann leiden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen verbessern die Isolation?', 5, '[{"text": "Sperrmechanismen", "correct": true, "because": "Schützen Daten"}, {"text": "Höheres Isolation Level", "correct": true, "because": "Mehr Konsistenz"}, {"text": "Schnelle CPU", "correct": false, "because": "Hardwarelösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Isolation Levels unwichtig?', 3, '[{"text": "Transaktionsschutz", "correct": false, "because": "Kernaufgabe"}, {"text": "Konsistenzgrad", "correct": false, "because": "Definiert Level"}, {"text": "GUI-Design", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Read Uncommitted Phantom Reads verhindern?', 3, '[{"text": "Nein", "correct": true, "because": "Bietet minimale Isolation"}, {"text": "Ja", "correct": false, "because": "Keine Schutzfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Serializable alle Anomalien ausschließt?', 2, '[{"text": "Ja", "correct": true, "because": "Höchste Isolation"}, {"text": "Nein", "correct": false, "because": "Hauptmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Isolation Level wähle ich für hohe Performance bei geringer Konsistenz?', 4, '[{"text": "Read Uncommitted", "correct": true, "because": "Minimale Sperren"}, {"text": "Serializable", "correct": false, "because": "Maximale Isolation"}, {"text": "Repeatable Read", "correct": false, "because": "Mittlere Isolation"}]');
